//! The loop definition of a state-feedback law (specification 35, C4, B1.4 and §17.1): pole placement, LQR or LQG. Ported from
//! `stateFeedbackLoopGenerator.ts` and from the state-feedback choices that `loopSetupForm.ts` checks. An LQG draft is generated by
//! `lqg_loop`, as the `TypeScript` dispatches it. Tune designs the gains (C4); the loop declares their parameter symbols and the
//! controller record that `tuning::state_controller` decodes.

#![allow(clippy::module_name_repetitions)] // `StateFeedbackLoopDraft` names the module's subject, as the TypeScript does.

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use super::catalog::{CompiledCatalog, CompiledController};
use super::loop_bindings::{
    binding, compiled, cyclic_task, explicit_experiment, loop_id, manual_output_type,
    measured_signal, measurement_binding, real_type, state_type, with_revision, FormSignal,
    MeasuredSignal,
};
use super::lqg_loop::lqg_loop_definition;
use super::pid_bindings::{startup_flag_is_bool, startup_reason, startup_state};
use super::pid_loop::{setpoint_signal, ModeChoice, SignalChoice};
use super::texts::generators as generator_texts;
use super::texts::save as texts;
use crate::failure::{Cause, Failure, NextAction};
use crate::loop_definition::{
    Action, AuxiliaryRole, AuxiliarySignal, ChannelInput, ChannelOutput, Controller, Design,
    Direction, Execution, Experiment, ExperimentKind, InitialValue, InitializedState, Limits,
    LoopChannels, LoopDefinition, LoopScope, LoopSignal, ModeBinding, ModeWhenTrue, Parameter,
    ParameterBinding, PostScan, SampleTiming, Signals, Topology, LOOP_SCHEMA_VERSION,
};
use crate::model::simulation::{ActuatorCapabilities, ActuatorKind};
use crate::model::GeneralModel;
use crate::tuning::state_controller::coefficients::ratio_unit;
use crate::tuning::state_controller::StateControllerFamily;

/// The convention of a state-feedback law: `du = −K·dx + N·dr` on the sampled deviations (C4).
pub(super) const CONVENTION: &str = "sampled-deviation-negative-feedback";

/// The most further measured outputs a state-feedback law feeds back, besides the controlled output (C4, D-B4).
pub(super) const MAXIMUM_FURTHER_OUTPUTS: usize = 3;

/// A further measured output of a state-feedback law: the output and the variable that holds its gain (C4).
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct FurtherOutput {
    /// The measured output.
    pub signal: FormSignal,
    /// The variable that holds the gain on this output.
    #[serde(default)]
    pub gain: String,
}

/// The estimator of an LQG law: the model file it implements, the measurement-noise variance and one row per model state (C4).
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct EstimatorDraft {
    /// The project's model file the estimator implements, relative to the project.
    #[serde(default)]
    pub model_file: String,
    /// The measurement-noise variance; absent when it is not a number.
    #[serde(default)]
    pub measurement_noise: Option<f64>,
    /// One row per state of the model file, in the model's order.
    #[serde(default)]
    pub states: Vec<EstimatorState>,
}

/// One state of an LQG estimator: its estimate's variable, the gain and observer gain on it, and its process-noise variance (C4).
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct EstimatorState {
    /// The variable that holds the estimate of this state.
    #[serde(default)]
    pub estimate: String,
    /// The variable that holds the gain on this estimate.
    #[serde(default)]
    pub gain: String,
    /// The variable that holds the observer gain of this estimate.
    #[serde(default)]
    pub observer_gain: String,
    /// The process-noise variance of this state; absent when it is not a number.
    #[serde(default)]
    pub process_noise: Option<f64>,
}

/// A state-feedback law as the setup form confirms it (`StateFeedbackLoopDraft` and the LQG draft of `loopSetupForm.ts`). Pole
/// placement and LQR name their gain and further outputs; LQG names its estimator. The setup asks for no experiment step or duration,
/// so both may be absent, and Identify chooses them (B3.3, B3.4).
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct StateFeedbackLoopDraft {
    /// The loop's name, from which its id is made.
    #[serde(default)]
    pub name: String,
    /// Whether the output rises (`direct`) or falls (`reverse`) while the measurement is below the setpoint.
    pub action: Action,
    /// The design: pole placement (`state-feedback`), `LQR` or `LQG`.
    pub family: StateControllerFamily,
    /// The compiled program or function block instance that runs the law.
    #[serde(default)]
    pub instance: String,
    /// The plant input.
    pub manipulated_variable: FormSignal,
    /// The controlled output.
    pub process_variable: FormSignal,
    /// The setpoint.
    pub setpoint: SignalChoice,
    /// The variable that holds the gain on the controlled output (pole placement and LQR).
    #[serde(default)]
    pub gain: String,
    /// The variable that holds the reference gain `N` (every design).
    #[serde(default)]
    pub reference_gain: String,
    /// The further measured outputs, each with the variable that holds its gain (pole placement and LQR).
    #[serde(default)]
    pub states: Vec<FurtherOutput>,
    /// The estimator (LQG).
    #[serde(default)]
    pub estimator: Option<EstimatorDraft>,
    /// The Auto/Manual signal, and the mode its TRUE value means.
    pub mode: ModeChoice,
    /// The manual output.
    #[serde(default)]
    pub manual_output: String,
    /// The identification experiment's output step; Identify chooses it when absent.
    pub experiment_step: Option<f64>,
    /// How long identification runs, in s; Identify chooses it when absent.
    pub experiment_duration_seconds: Option<f64>,
    /// The BOOL the program sets when its startup code has run.
    pub startup_flag: Option<String>,
}

impl StateFeedbackLoopDraft {
    /// The model file an LQG estimator implements, when the draft names one. The engine reads that file before the loop is generated.
    #[must_use]
    pub fn estimator_model_file(&self) -> Option<&str> {
        if self.family != StateControllerFamily::Lqg {
            return None;
        }
        self.estimator
            .as_ref()
            .map(|estimator| estimator.model_file.as_str())
            .filter(|file| !file.trim().is_empty())
    }
}

/// A further output the form has checked: its measured signal and the variable that holds its gain.
#[derive(Debug, Clone, PartialEq)]
pub(super) struct FurtherChoice {
    /// The measured output.
    pub signal: MeasuredSignal,
    /// The variable that holds the gain on this output.
    pub gain: String,
}

/// The loop definition of a state-feedback law (`stateFeedbackLoopDefinition`): pole placement or LQR on the measured outputs, or LQG
/// through `lqg_loop` with the estimator's model. `estimator` is the model file an LQG estimator implements, read by the engine; the
/// other families take no model.
///
/// # Errors
/// The form leaves a choice unset or breaks one of its rules, the program writes a seeded value or initializes the loop's
/// controller and the draft names no startup-done flag, the instance is not a compiled program or function block that runs in
/// exactly one cyclic task, a symbol is not compiled or is not `REAL` or `LREAL`, or a signal is computed by the program.
pub fn state_feedback_loop_definition(
    catalog: &CompiledCatalog,
    scope: &LoopScope,
    draft: &StateFeedbackLoopDraft,
    estimator: Option<&GeneralModel>,
) -> Result<LoopDefinition, Failure> {
    let (manipulated, process) = common_choices(draft)?;
    if draft.family == StateControllerFamily::Lqg {
        return lqg_loop_definition(catalog, scope, draft, &manipulated, &process, estimator);
    }
    let further = law_choices(draft, &process)?;
    check_startup(
        catalog,
        &draft.instance,
        &law_seeded(draft, &further),
        draft.startup_flag.as_deref(),
    )?;
    law_loop(catalog, scope, draft, &manipulated, &process, &further)
}

/// The name, the instance, the two signals and the setpoint, checked in the order of `loopSetupForm.ts`.
///
/// # Errors
/// The name, the instance, the setpoint or a signal is not chosen, or a signal's range is not an interval.
pub(super) fn common_choices(
    draft: &StateFeedbackLoopDraft,
) -> Result<(MeasuredSignal, MeasuredSignal), Failure> {
    if draft.name.trim().is_empty() {
        return Err(settings(texts::name_needed()).with_field("name"));
    }
    if draft.instance.trim().is_empty() {
        return Err(
            settings(texts::state_feedback_instance_needed()).with_field("feedback.instance")
        );
    }
    let manipulated = form_signal(
        &draft.manipulated_variable,
        "plant input",
        Some("feedback.manipulatedVariable"),
    )?;
    let process = form_signal(
        &draft.process_variable,
        "controlled output",
        Some("feedback.processVariable"),
    )?;
    if draft.setpoint.symbol.trim().is_empty() {
        return Err(settings(texts::setpoint_needed()).with_field("feedback.setpoint"));
    }
    Ok((manipulated, process))
}

/// The gain, the reference gain and the further outputs of a pole-placement or LQR law, checked in the order of `loopSetupForm.ts`,
/// with the mode and the manual output.
///
/// # Errors
/// A gain or the reference gain is not chosen, a further output has no gain or range, no further output is chosen, or the mode or
/// the manual output is not chosen.
fn law_choices(
    draft: &StateFeedbackLoopDraft,
    process: &MeasuredSignal,
) -> Result<Vec<FurtherChoice>, Failure> {
    if draft.gain.trim().is_empty() {
        return Err(settings(&texts::gain_needed(&process.symbol)).with_field("feedback.gain"));
    }
    if draft.reference_gain.trim().is_empty() {
        return Err(settings(texts::reference_gain_needed()).with_field("feedback.referenceGain"));
    }
    let further = further_outputs(&draft.states)?;
    if further.is_empty() {
        return Err(settings(texts::further_output_needed()));
    }
    mode_and_manual("feedback", &draft.mode, &draft.manual_output)?;
    Ok(further)
}

/// The further outputs the form sends with a symbol, each checked as a signal and with its gain (`loopSetupForm.ts`). A row with no
/// symbol is not a further output, as the form has it.
///
/// # Errors
/// A further output has no symbol-complete signal or no gain.
pub(super) fn further_outputs(states: &[FurtherOutput]) -> Result<Vec<FurtherChoice>, Failure> {
    let mut further = Vec::new();
    for state in states
        .iter()
        .filter(|state| !state.signal.symbol.trim().is_empty())
    {
        let signal = form_signal(
            &state.signal,
            &format!("measured output {}", state.signal.symbol),
            None,
        )?;
        if state.gain.trim().is_empty() {
            return Err(settings(&texts::gain_needed(&state.signal.symbol)));
        }
        further.push(FurtherChoice {
            signal,
            gain: state.gain.clone(),
        });
    }
    Ok(further)
}

/// A signal of the form, with its symbol, unit and range (`signal` of `loopSetupForm.ts`). `label` names its role in the sentences.
///
/// # Errors
/// The symbol or the unit is blank, the minimum or maximum is not a number, or the maximum is not above the minimum.
pub(super) fn form_signal(
    signal: &FormSignal,
    label: &str,
    field: Option<&str>,
) -> Result<MeasuredSignal, Failure> {
    measured_signal(signal, label, field)
}

/// The Auto/Manual signal and the manual output, checked after the law's own choices (`loopSetupForm.ts`).
///
/// # Errors
/// The mode's symbol or the manual output is blank.
pub(super) fn mode_and_manual(
    prefix: &str,
    mode: &ModeChoice,
    manual_output: &str,
) -> Result<(), Failure> {
    if mode.symbol.trim().is_empty() {
        return Err(settings(texts::mode_needed()).with_field(&format!("{prefix}.mode")));
    }
    if manual_output.trim().is_empty() {
        return Err(
            settings(texts::manual_output_needed()).with_field(&format!("{prefix}.manualOutput"))
        );
    }
    Ok(())
}

/// The startup-done flag the program needs (C1 Setup; `startupFlag` of `loopSetupForm.ts`): a program that writes a seeded value, or
/// initializes the loop's controller, needs the flag, and a draft that names one passes if the flag is a compiled `BOOL`.
///
/// # Errors
/// The program needs the flag, and the draft names none.
pub(super) fn check_startup(
    catalog: &CompiledCatalog,
    instance: &str,
    seeded: &[String],
    flag: Option<&str>,
) -> Result<(), Failure> {
    if let Some(flag) = flag.filter(|flag| !flag.is_empty()) {
        return startup_flag_is_bool(catalog, flag);
    }
    let no_records: Vec<String> = Vec::new();
    match startup_reason(catalog, Some(instance), seeded, &no_records) {
        Some(reason) => {
            Err(settings(&generator_texts::startup_flag_needed(&reason)).with_field("startupFlag"))
        }
        None => Ok(()),
    }
}

/// The symbols that validation seeds for a pole-placement or LQR law, in the order of `loopSetupForm.ts`'s `seededWrite`.
fn law_seeded(draft: &StateFeedbackLoopDraft, further: &[FurtherChoice]) -> Vec<String> {
    let mut seeded = vec![
        draft.setpoint.symbol.clone(),
        draft.gain.clone(),
        draft.reference_gain.clone(),
    ];
    seeded.extend(further.iter().map(|state| state.gain.clone()));
    seeded.push(draft.manual_output.clone());
    seeded.push(draft.mode.symbol.clone());
    seeded
}

/// The loop of a pole-placement or LQR law: its program, its gains and reference gain, its record and its channels (C4).
///
/// # Errors
/// The instance is not a compiled program or function block, it does not run in exactly one cyclic task, more further outputs than the
/// setup holds are given, a symbol is not compiled or is not `REAL` or `LREAL`, or a signal is computed by the program.
fn law_loop(
    catalog: &CompiledCatalog,
    scope: &LoopScope,
    draft: &StateFeedbackLoopDraft,
    manipulated: &MeasuredSignal,
    process: &MeasuredSignal,
    further: &[FurtherChoice],
) -> Result<LoopDefinition, Failure> {
    let program = instance_program(catalog, &draft.instance)?;
    let task = cyclic_task(program)?;
    if further.len() > MAXIMUM_FURTHER_OUTPUTS {
        return Err(settings(texts::further_outputs_limit()));
    }
    let manual = compiled(catalog, &draft.manual_output)?;
    let setpoint = setpoint_signal(&draft.setpoint, process);
    let startup = startup_states(draft.startup_flag.as_deref());
    let record = law_record(draft.family, &gain_symbols(draft, further), draft, &startup);
    let controller = Controller {
        instance: draft.instance.clone(),
        type_name: program.type_name.clone(),
        revision: "sha256:unverified".to_string(),
        action: draft.action,
        task_period_ms: task.interval_ms,
        design: Some(Design::Project),
        law: None,
        mode_signal: Some(draft.mode.symbol.clone()),
        mode_when_true: Some(draft.mode.when_true),
        tracking_signal: None,
        manual_output_signal: Some(manual.symbol.clone()),
        manual_output_address: manual.address.clone().filter(|address| !address.is_empty()),
        manual_output_type: Some(manual_output_type(real_type(manual)?)),
        manual_output_follows_output: None,
        pid_initialization: None,
        state_feedback: Some(record),
        on_off: None,
        project: None,
        group: None,
    };
    let parameters = law_parameters(catalog, draft, manipulated, process, &setpoint, further)?;
    let signals = law_signals(catalog, manipulated, process, &setpoint, further)?;
    let experiment = explicit_experiment(
        &draft.name,
        Execution::ControlStudio,
        ExperimentKind::MvStep,
        draft.experiment_step,
        draft.experiment_duration_seconds,
    )?;
    Ok(assemble(
        scope,
        StateLawParts {
            name: draft.name.clone(),
            controller,
            signals,
            channels: Some(law_channels(manipulated, process, further)),
            identification_policy: Some(identification_policy()),
            limits: output_limits(manipulated),
            period_ms: task.interval_ms,
            task_name: task.name.clone(),
            mode: mode_binding(&draft.mode),
            parameters,
            experiment,
        },
    ))
}

/// The gains of a pole-placement or LQR law, in the order of its measured outputs: the controlled output first (C4).
fn gain_symbols(draft: &StateFeedbackLoopDraft, further: &[FurtherChoice]) -> Vec<String> {
    let mut gains = vec![draft.gain.clone()];
    gains.extend(further.iter().map(|state| state.gain.clone()));
    gains
}

/// The controller record of a state law, as `tuning::state_controller` decodes it (C4): the family, the convention, the gain rows, the
/// reference gain row, and the declared initialization.
pub(super) fn law_record(
    family: StateControllerFamily,
    gains: &[String],
    draft: &StateFeedbackLoopDraft,
    startup: &[InitializedState],
) -> Value {
    json!({
        "family": family_name(family),
        "convention": CONVENTION,
        "gainSymbols": [gains],
        "referenceGainSymbols": [[draft.reference_gain.as_str()]],
        "initialization": { "kind": "declared-state-v1", "states": json_of(startup) },
    })
}

/// The startup-done flag as a declared state of a law's initialization, when the draft names one (C1 Setup).
pub(super) fn startup_states(flag: Option<&str>) -> Vec<InitializedState> {
    flag.filter(|flag| !flag.is_empty())
        .map(startup_state)
        .into_iter()
        .collect()
}

/// The parameters of a pole-placement or LQR law: the gain on the controlled output, the gains on the further outputs, then the
/// reference gain (`stateFeedbackLoopDefinition`'s `coefficient`).
///
/// # Errors
/// A variable is not compiled, or it is not `REAL` or `LREAL`.
fn law_parameters(
    catalog: &CompiledCatalog,
    draft: &StateFeedbackLoopDraft,
    manipulated: &MeasuredSignal,
    process: &MeasuredSignal,
    setpoint: &MeasuredSignal,
    further: &[FurtherChoice],
) -> Result<Vec<Parameter>, Failure> {
    let mut parameters = vec![gain_parameter(
        catalog,
        &draft.gain,
        process,
        manipulated,
        format!("State feedback gain on {}", process.symbol),
    )?];
    for state in further {
        parameters.push(gain_parameter(
            catalog,
            &state.gain,
            &state.signal,
            manipulated,
            format!("State feedback gain on {}", state.signal.symbol),
        )?);
    }
    parameters.push(gain_parameter(
        catalog,
        &draft.reference_gain,
        process,
        manipulated,
        format!("Reference gain on {}", setpoint.symbol),
    )?);
    Ok(parameters)
}

/// The signals of a pole-placement or LQR law: the setpoint and the output, the controlled output, and each further output as a state.
///
/// # Errors
/// A signal is not compiled, is not `REAL` or `LREAL`, or is a measurement the program computes.
fn law_signals(
    catalog: &CompiledCatalog,
    manipulated: &MeasuredSignal,
    process: &MeasuredSignal,
    setpoint: &MeasuredSignal,
    further: &[FurtherChoice],
) -> Result<Signals, Failure> {
    let mut additional = Vec::with_capacity(further.len());
    for (index, state) in further.iter().enumerate() {
        let signal = measurement_binding(catalog, &state.signal)?;
        additional.push(auxiliary_state(index, signal));
    }
    Ok(Signals {
        setpoint: Some(binding(catalog, setpoint, Direction::Read)?),
        process_variable: measurement_binding(catalog, process)?,
        manipulated_variable: binding(catalog, manipulated, Direction::Write)?,
        actuator: None,
        additional: Some(additional),
    })
}

/// The channels of a pole-placement or LQR law: the plant input, the controlled output with its setpoint, and each further output as
/// a state (C4; `stateFeedbackLoopDefinition`'s `channels`).
fn law_channels(
    manipulated: &MeasuredSignal,
    process: &MeasuredSignal,
    further: &[FurtherChoice],
) -> LoopChannels {
    let mut outputs = vec![ChannelOutput {
        model_channel_id: process.symbol.clone(),
        signal_id: "processVariable".to_string(),
        setpoint_signal_id: Some("setpoint".to_string()),
        requirements: None,
    }];
    for (index, state) in further.iter().enumerate() {
        outputs.push(ChannelOutput {
            model_channel_id: state.signal.symbol.clone(),
            signal_id: state_signal_id(index),
            setpoint_signal_id: None,
            requirements: None,
        });
    }
    LoopChannels {
        inputs: vec![manipulated_input(manipulated, manipulated.symbol.clone())],
        outputs,
        initial_state: None,
    }
}

/// The plant input as a channel input: a continuous actuator over the signal's range (C4).
pub(super) fn manipulated_input(
    manipulated: &MeasuredSignal,
    model_channel_id: String,
) -> ChannelInput {
    ChannelInput {
        model_channel_id,
        signal_id: "manipulatedVariable".to_string(),
        manual_output_signal: None,
        manual_output_type: None,
        applied_signal_id: None,
        actuator: ActuatorCapabilities {
            kind: ActuatorKind::Continuous,
            minimum: manipulated.minimum,
            maximum: manipulated.maximum,
            rate_up_per_s: None,
            rate_down_per_s: None,
            minimum_on_seconds: None,
            minimum_off_seconds: None,
        },
        experiment_step: None,
    }
}

/// The identifier of the further output `index` (from zero) in the loop's signals: `state-2` for the first, as the `TypeScript` names it.
pub(super) fn state_signal_id(index: usize) -> String {
    format!("state-{}", index + 2)
}

/// A further output as an auxiliary state signal of the loop (C4).
fn auxiliary_state(index: usize, signal: LoopSignal) -> AuxiliarySignal {
    let id = state_signal_id(index);
    AuxiliarySignal {
        id: id.clone(),
        channel: id,
        role: AuxiliaryRole::State,
        symbol: signal.symbol,
        address: signal.address,
        iec_type: signal.iec_type,
        direction: signal.direction,
        unit: signal.unit,
        range: signal.range,
    }
}

/// One gain as a parameter (C0; `coefficient` of `stateFeedbackLoopGenerator.ts`). Its unit is the input's per the output's. Its range is
/// `1000` times the input's span per the output's span: a larger coefficient would move the input across its whole range for a
/// thousandth of the output's range.
///
/// # Errors
/// The variable is not compiled, or it is not `REAL` or `LREAL`.
pub(super) fn gain_parameter(
    catalog: &CompiledCatalog,
    symbol: &str,
    output: &MeasuredSignal,
    input: &MeasuredSignal,
    convention: String,
) -> Result<Parameter, Failure> {
    let limit = 1000.0 * (input.maximum - input.minimum) / (output.maximum - output.minimum);
    Ok(Parameter {
        symbol: symbol.to_string(),
        iec_type: real_type(compiled(catalog, symbol)?)?,
        unit: ratio_unit(&input.unit, &output.unit),
        convention,
        minimum: -limit,
        maximum: limit,
    })
}

/// The loop with its identity, its controller and signals, its parameter record and the rest that a state law declares (C4).
pub(super) struct StateLawParts {
    /// The loop's name.
    pub name: String,
    /// The controller that runs the law.
    pub controller: Controller,
    /// The loop's signals.
    pub signals: Signals,
    /// The loop's channels, when the law has them.
    pub channels: Option<LoopChannels>,
    /// How Identify treats the plant, when the law declares it.
    pub identification_policy: Option<Value>,
    /// The output's limits.
    pub limits: Limits,
    /// The period of the task that runs the controller, in ms.
    pub period_ms: f64,
    /// The task's name.
    pub task_name: String,
    /// The Auto/Manual signal's binding.
    pub mode: ModeBinding,
    /// The parameters of the law's record.
    pub parameters: Vec<Parameter>,
    /// The identification experiment, when both its step and its duration are set.
    pub experiment: Option<Experiment>,
}

/// The loop definition of a state law, with its id, its revision and the scope it is opened for (`withRevision`, B1.4).
pub(super) fn assemble(scope: &LoopScope, parts: StateLawParts) -> LoopDefinition {
    let id = loop_id(&parts.name);
    with_revision(LoopDefinition {
        schema_version: LOOP_SCHEMA_VERSION,
        id: id.clone(),
        name: parts.name,
        revision: "sha256:pending".to_string(),
        project_id: scope.project_id.clone(),
        runtime_id: scope.runtime_id.clone(),
        controller: parts.controller,
        signals: parts.signals,
        limits: parts.limits,
        observed_sample_timing: SampleTiming {
            nominal_period_ms: parts.period_ms,
            maximum_jitter_ms: None,
        },
        parameter_binding: Some(ParameterBinding {
            loop_id: id,
            task_name: parts.task_name,
            mode: parts.mode,
            parameters: parts.parameters,
        }),
        parameter_purpose: None,
        topology: Some(Topology::ClosedLoop),
        experiment: parts.experiment,
        plant_id: None,
        operating_point: None,
        identification_policy: parts.identification_policy,
        verification_scenarios: None,
        channels: parts.channels,
        analysis: None,
        analysis_parameter_symbols: None,
        cascade: None,
    })
}

/// The identification policy of a state law: a first-order model of each measured output, with open-loop and sustained-hold tests
/// (C4 Identify, `identificationPolicy`).
pub(super) fn identification_policy() -> Value {
    json!({
        "maximumOrder": 1,
        "openLoopPermitted": true,
        "sustainedHoldPermitted": true,
        "information": "basic",
    })
}

/// The output's limits, which are the plant input's range (`limits` of `stateFeedbackLoopGenerator.ts`).
pub(super) fn output_limits(manipulated: &MeasuredSignal) -> Limits {
    Limits {
        output_minimum: Some(manipulated.minimum),
        output_maximum: Some(manipulated.maximum),
        rate_up_per_s: None,
        rate_down_per_s: None,
        expected_settling_seconds: None,
    }
}

/// The Auto/Manual binding of a state law: its signal, and whether TRUE means Manual (C0).
pub(super) fn mode_binding(mode: &ModeChoice) -> ModeBinding {
    ModeBinding {
        symbol: mode.symbol.clone(),
        manual_value: mode.when_true == ModeWhenTrue::Manual,
    }
}

/// The compiled program or function block that runs the law, with the instance's name (`stateFeedbackLoopDefinition`).
///
/// # Errors
/// No compiled program or function block has the instance.
pub(super) fn instance_program<'a>(
    catalog: &'a CompiledCatalog,
    instance: &str,
) -> Result<&'a CompiledController, Failure> {
    catalog
        .controllers
        .iter()
        .find(|entry| entry.instance == instance)
        .ok_or_else(|| {
            Failure::new(
                &generator_texts::not_compiled_program(instance),
                Cause::Implementation,
                NextAction::OpenLoopSetup,
            )
        })
}

/// The name of a design as the loop file writes it.
pub(super) fn family_name(family: StateControllerFamily) -> &'static str {
    match family {
        StateControllerFamily::StateFeedback => "state-feedback",
        StateControllerFamily::Lqr => "LQR",
        StateControllerFamily::Lqg => "LQG",
    }
}

/// A value as a loop file holds it. These records always serialize; the default (null) would only be refused by the loop contract.
pub(super) fn json_of<T: Serialize + ?Sized>(value: &T) -> Value {
    serde_json::to_value(value).unwrap_or_default()
}

/// A state the controller declares that starts at zero, the operating point, and may move within its bounds (C4; the estimates of
/// `lqgLoopGenerator.ts`). Its type is its variable's real type as a state type.
///
/// # Errors
/// The variable is not compiled, or it is not `REAL` or `LREAL`.
pub(super) fn zero_started_state(
    catalog: &CompiledCatalog,
    symbol: &str,
    unit: String,
    bounds: (f64, f64),
) -> Result<InitializedState, Failure> {
    Ok(InitializedState {
        symbol: symbol.to_string(),
        iec_type: state_type(real_type(compiled(catalog, symbol)?)?),
        unit,
        minimum: bounds.0,
        maximum: bounds.1,
        initial: InitialValue::Constant(0.0),
        post_scan: PostScan::Bounded,
    })
}

/// A settings refusal that the setup form's next action answers (A11.2).
pub(super) fn settings(text: &str) -> Failure {
    Failure::new(text, Cause::Settings, NextAction::OpenLoopSetup)
}

